      }
    } else if (trimmed.endsWith(".ts") && !trimmed.includes(" ")) {
      paths.push(trimmed);
    }
  }
  return paths;
}

function isTestFile(path: string): boolean {
  const base = path.split("/").pop() ?? path;
  return base.endsWith(".test.ts") || base.endsWith(".spec.ts");
}

// Test files are consumers, not modules of the repository, so they are not
// indexed. Sorting keeps the candidate order deterministic regardless of the
// order the filesystem server walks the directory in.
function selectModuleFiles(paths: string[]): string[] {
  const modules: string[] = [];
  for (const p of paths) {
    if (!isTestFile(p)) {
      modules.push(p);
    }
  }
  return modules.sort();
}

function countLines(source: string): number {
  const withoutTrailingWhitespace = source.replace(/\s+$/, "");
  if (withoutTrailingWhitespace === "") {
    return 0;
  }
  return withoutTrailingWhitespace.split("\n").length;
}

