  return names;
}

function moduleObservations(lines: number, names: string[]): string[] {
  const exportList = names.length > 0 ? names.join(", ") : "none";
  return [`${lines} lines`, `exports: ${exportList}`];
}

function recordModule(indexed: ModuleRecord[], path: string, lines: number) {
  indexed.push({ path, lines });
