    }
  }

  const relations = moduleRelations(indexed, input.root);
  await tools.memory.createRelations({ relations });

  const expectedEntities = 1 + indexed.length;
  let settled = false;
  let settleAttempts = 0;
  while (!settled && settleAttempts < 3) {
    settleAttempts += 1;
    const graph = await tools.memory.readGraph({});
    settled = graph.entities.length >= expectedEntities;
  }

  const report = buildReport(indexed, failures);
  const reportPath = reportPathFor(input.root);
  await tools.fs.writeFile({ path: reportPath, content: report });

  return {
    indexedModules: indexed.length,
    failedModules: failures.length,
    graphReadAttempts: settleAttempts
