}

import type { Tools } from "../generated/tools";

const NORTH_FILE = "drop-north.csv";

interface RejectEntry {
  id: string;
  reason: string;
}

interface FoldResult {
  folded: number;
  rejected: number;
}

function findDropFiles(listing: string): string[] {
  return listing
    .split("\n")
    .map((line) => line.replace(/^\[[A-Z]+\]\s*/, "").trim())
    .filter((name) => name.startsWith("drop-") && name.endsWith(".csv"));
}

function newTotals(): Map<string, number> {
  return new Map<string, number>();
}

// Folds the data rows of one drop file (header skipped) into the shared totals,
// honouring the remaining row budget. Returns how many rows were folded/rejected.
function foldRows(
  content: string,
  budget: number,
  totals: Map<string, number>,
  rejects: RejectEntry[]
): FoldResult {
  const rows = content
    .split("\n")
    .map((row) => row.trim())
    .filter((row) => row.length > 0);

  let folded = 0;
  let rejected = 0;

  for (const row of rows.slice(1)) {
    if (folded >= budget) {
      break;
    }

    const columns = row.split(",");
    const id = (columns[0] ?? "").trim();
    const region = (columns[1] ?? "").trim();
    const amountRaw = (columns[2] ?? "").trim();

    if (region === "") {
      rejected += 1;
      rejects.push({ id, reason: "empty-region" });
      continue;
    }

    if (amountRaw === "" || !Number.isFinite(Number(amountRaw))) {
      rejected += 1;
      rejects.push({ id, reason: "amount-not-a-number" });
      continue;
    }

    const amount = Number(amountRaw);
    totals.set(region, (totals.get(region) ?? 0) + amount);
    folded += 1;
  }

  return { folded, rejected };
}

function renderLedger(totals: Map<string, number>): string {
  const lines: string[] = [];
  for (const [region, total] of totals) {
    lines.push(`${region}: ${total.toFixed(2)}`);
  }
  return lines.join("\n");
}

function renderRejects(rejects: RejectEntry[]): string {
  const lines: string[] = [];
  for (const entry of rejects) {
    lines.push(`${entry.id}: ${entry.reason}`);
  }
  return lines.join("\n");
}

export default async function flow(
  input: { root: string; maxRows: number },
  tools: Tools
) {
  const listing = await tools.fs.listDirectory({ path: input.root });
  const dropFiles = findDropFiles(listing.content);

  if (dropFiles.length === 0) {
    return { folded: 0, reason: "no-drops" };
  }

  const totals = newTotals();
  const rejects: RejectEntry[] = [];
  let folded = 0;
  let rejected = 0;
  let missingRegions = 0;

  // drop-north.csv is expected to be absent; a failed read is a missing region,
  // not a fatal error.
  try {
    const northFile = await tools.fs.readTextFile({
      path: `${input.root}/${NORTH_FILE}`
    });
    const northResult = foldRows(northFile.content, input.maxRows - folded, totals, rejects);
    folded += northResult.folded;
    rejected += northResult.rejected;
  } catch {
    missingRegions += 1;
  }

  for (const fileName of dropFiles) {
    if (fileName === NORTH_FILE) {
      continue;
    }

    if (folded >= input.maxRows) {
      break;
    }

    const dropFile = await tools.fs.readTextFile({
      path: `${input.root}/${fileName}`
    });
    const fileResult = foldRows(dropFile.content, input.maxRows - folded, totals, rejects);
    folded += fileResult.folded;
    rejected += fileResult.rejected;
  }

  const ledgerMarkdown = renderLedger(totals);
  await tools.fs.writeFile({ path: `${input.root}/ledger.md`, content: ledgerMarkdown });

  const rejectsMarkdown = renderRejects(rejects);
  await tools.fs.writeFile({ path: `${input.root}/rejects.md`, content: rejectsMarkdown });

  return { folded, rejected, missingRegions };
}

import type { Tools } from "../generated/tools";

type DocStatus = "fresh" | "stale" | "missing";

interface ModuleAudit {
  modulePath: string;
  docPath: string;
  status: DocStatus;
}

function parseModulePaths(listing: string): string[] {
  return listing
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => line.length > 0);
}

function isTestModule(modulePath: string): boolean {
  return modulePath.endsWith(".test.ts");
}

function pickAuditableModules(paths: string[], limit: number): string[] {
  return paths.filter((path) => !isTestModule(path)).slice(0, Math.max(limit, 0));
}

function docPathFor(root: string, modulePath: string): string {
  const segments = modulePath.split(/[\\/]/);
  const fileName = segments[segments.length - 1] ?? modulePath;
  const baseName = fileName.replace(/\.ts$/, "");
  return `${root}/docs/${baseName}.md`;
}

function extractModifiedTime(fileInfo: string): number | null {
  for (const line of fileInfo.split(/\r?\n/)) {
    if (!line.toLowerCase().includes("modified")) {
      continue;
    }
    const value = line.slice(line.lastIndexOf(":") + 1).trim();
    const parsed = Date.parse(value);
    if (!Number.isNaN(parsed)) {
      return parsed;
    }
  }
  return null;
}

function isDocStale(docInfo: string, moduleInfo: string): boolean {
  const docTime = extractModifiedTime(docInfo);
  const moduleTime = extractModifiedTime(moduleInfo);
  if (docTime === null || moduleTime === null) {
    return false;
  }
  return docTime < moduleTime;
}

function classifyAudit(
  modulePath: string,
  docPath: string,
  moduleInfo: string,
  docInfo: string
): ModuleAudit {
  const status: DocStatus = isDocStale(docInfo, moduleInfo) ? "stale" : "fresh";
  return { modulePath, docPath, status };
}

function missingAudit(modulePath: string, docPath: string): ModuleAudit {
  return { modulePath, docPath, status: "missing" };
}

function recordAudit(audits: ModuleAudit[], audit: ModuleAudit): void {
  audits.push(audit);
}

function renderFreshnessReport(audits: ModuleAudit[]): string {
  const lines: string[] = ["# Documentation freshness", ""];
  for (const audit of audits) {
    lines.push(`- ${audit.modulePath}: ${audit.status}`);
  }
  return `${lines.join("\n")}\n`;
}

function countWithStatus(audits: ModuleAudit[], status: DocStatus): number {
  return audits.filter((audit) => audit.status === status).length;
}

export default async function flow(
  input: { root: string; maxModules: number },
  tools: Tools
) {
  const searchResults = await tools.fs.searchFiles({ path: input.root, pattern: "*.ts" });
  const modulePaths = parseModulePaths(searchResults.content);

  if (modulePaths.length === 0) {
    return { audited: 0 };
  }

  const modules = pickAuditableModules(modulePaths, input.maxModules);
  const audits: ModuleAudit[] = [];

  for (const modulePath of modules) {
    const docPath = docPathFor(input.root, modulePath);
    let audit: ModuleAudit;
    try {
      const [moduleInfo, docInfo] = await Promise.all([
        tools.fs.getFileInfo({ path: modulePath }),
        tools.fs.getFileInfo({ path: docPath })
      ]);
      const classified = classifyAudit(modulePath, docPath, moduleInfo.content, docInfo.content);
      audit = classified;
    } catch {
      const missed = missingAudit(modulePath, docPath);
      audit = missed;
    }
    recordAudit(audits, audit);
  }

  for (const audit of audits) {
    if (audit.status !== "stale") {
      continue;
    }
    await tools.memory.createEntities({
      entities: [
        { name: audit.docPath, entityType: "stale-doc", observations: [audit.modulePath] }
      ]
    });
  }

  const report = renderFreshnessReport(audits);
  await tools.fs.writeFile({ path: `${input.root}/freshness.md`, content: report });

  const staleCount = countWithStatus(audits, "stale");
  const missingCount = countWithStatus(audits, "missing");

  return { audited: audits.length, stale: staleCount, missing: missingCount };
}

import type { Tools } from "../generated/tools";

type DocStatus = "fresh" | "stale" | "missing";

interface ModuleAudit {
  modulePath: string;
  docPath: string;
  status: DocStatus;
}

function parseModulePaths(listing: string): string[] {
  return listing
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => line.endsWith(".ts"));
}

function isTestModule(modulePath: string): boolean {
  return modulePath.endsWith(".test.ts");
}

function pickAuditableModules(paths: string[], limit: number): string[] {
  return paths.filter((path) => !isTestModule(path)).slice(0, Math.max(limit, 0));
}

function docPathFor(root: string, modulePath: string): string {
  const segments = modulePath.split(/[\\/]/);
  const fileName = segments[segments.length - 1] ?? modulePath;
  const baseName = fileName.replace(/\.ts$/, "");
  return `${root}/docs/${baseName}.md`;
}

function modifiedTimeFromJson(text: string): number | null {
  try {
    const data = JSON.parse(text) as Record<string, unknown>;
    const raw = data["modified"];
    if (typeof raw === "number") {
      return raw;
    }
    if (typeof raw === "string") {
      const parsed = Date.parse(raw);
      if (!Number.isNaN(parsed)) {
        return parsed;
      }
    }
  } catch {
    // Not JSON — the text scanners below will handle it.
  }
  return null;
}

function modifiedTimeFromQuotedField(text: string): number | null {
  const match = text.match(/"modified"\s*:\s*"([^"]+)"/);
  if (match === null) {
    return null;
  }
  const parsed = Date.parse(match[1]);
  return Number.isNaN(parsed) ? null : parsed;
}

function modifiedTimeFromLines(text: string): number | null {
  for (const line of text.split(/\r?\n/)) {
    const keyIndex = line.toLowerCase().indexOf("modified");
    if (keyIndex === -1) {
      continue;
    }
    const value = line
      .slice(keyIndex + "modified".length)
      .replace(/^[\s:"']+/, "")
      .replace(/["',\s]+$/, "");
    const parsed = Date.parse(value);
    if (!Number.isNaN(parsed)) {
      return parsed;
    }
  }
  return null;
}

function extractModifiedTime(fileInfo: string): number | null {
  const fromJson = modifiedTimeFromJson(fileInfo);
  if (fromJson !== null) {
    return fromJson;
  }
  const fromQuoted = modifiedTimeFromQuotedField(fileInfo);
  if (fromQuoted !== null) {
    return fromQuoted;
  }
  return modifiedTimeFromLines(fileInfo);
}

function isDocStale(docInfo: string, moduleInfo: string): boolean {
  const docTime = extractModifiedTime(docInfo);
  const moduleTime = extractModifiedTime(moduleInfo);
  if (docTime === null || moduleTime === null) {
    return false;
  }
  return docTime < moduleTime;
}

function classifyAudit(
  modulePath: string,
  docPath: string,
  moduleInfo: string,
  docInfo: string
): ModuleAudit {
  const status: DocStatus = isDocStale(docInfo, moduleInfo) ? "stale" : "fresh";
  return { modulePath, docPath, status };
}

function missingAudit(modulePath: string, docPath: string): ModuleAudit {
  return { modulePath, docPath, status: "missing" };
}

function recordAudit(audits: ModuleAudit[], audit: ModuleAudit): void {
  audits.push(audit);
}

function renderFreshnessReport(audits: ModuleAudit[]): string {
  const lines: string[] = ["# Documentation freshness", ""];
  for (const audit of audits) {
    lines.push(`- ${audit.modulePath} -> ${audit.docPath}: ${audit.status}`);
  }
  return `${lines.join("\n")}\n`;
}

function countWithStatus(audits: ModuleAudit[], status: DocStatus): number {
  return audits.filter((audit) => audit.status === status).length;
}

export default async function flow(
  input: { root: string; maxModules: number },
  tools: Tools
) {
  const searchResults = await tools.fs.searchFiles({ path: input.root, pattern: "*.ts" });
  const modulePaths = parseModulePaths(searchResults.content);

  if (modulePaths.length === 0) {
    return { audited: 0 };
  }

  const modules = pickAuditableModules(modulePaths, input.maxModules);
  const audits: ModuleAudit[] = [];

  for (const modulePath of modules) {
    const docPath = docPathFor(input.root, modulePath);
    try {
      const [moduleInfo, docInfo] = await Promise.all([
        tools.fs.getFileInfo({ path: modulePath }),
        tools.fs.getFileInfo({ path: docPath })
      ]);
      const audit = classifyAudit(modulePath, docPath, moduleInfo.content, docInfo.content);
      recordAudit(audits, audit);
    } catch {
      const missed = missingAudit(modulePath, docPath);
      recordAudit(audits, missed);
    }
  }

  for (const audit of audits) {
    if (audit.status !== "stale") {
      continue;
    }
    await tools.memory.createEntities({
      entities: [
        { name: audit.docPath, entityType: "stale-doc", observations: [audit.modulePath] }
      ]
    });
  }

  const report = renderFreshnessReport(audits);
  await tools.fs.writeFile({ path: `${input.root}/freshness.md`, content: report });

  const staleCount = countWithStatus(audits, "stale");
  const missingCount = countWithStatus(audits, "missing");

  return { audited: audits.length, stale: staleCount, missing: missingCount };
}

import type { Tools } from "../generated/tools";

interface IndexedModule {
  path: string;
  lines: number;
}

interface GraphRelation {
  from: string;
  to: string;
  relationType: string;
}

function parsePaths(content: string): string[] {
  return content
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length > 0);
}

function limitTo(paths: string[], max: number): string[] {
  return paths.slice(0, Math.max(0, max));
}

function countLines(content: string): number {
  if (content.length === 0) {
    return 0;
  }
  return content.split("\n").length;
}

function extractExports(source: string): string[] {
  const names = new Set<string>();
  const declarationPattern =
    /export\s+(?:default\s+)?(?:declare\s+)?(?:async\s+)?(?:function|class|interface|type|enum|const|let|var)\s+([A-Za-z0-9_$]+)/g;
  const listPattern = /export\s*\{([^}]*)\}/g;

  for (const match of source.matchAll(declarationPattern)) {
    names.add(match[1]);
  }

  for (const match of source.matchAll(listPattern)) {
    for (const part of match[1].split(",")) {
      const trimmed = part.trim();
      if (trimmed.length === 0) {
        continue;
      }
      const name = trimmed.split(/\s+as\s+/).pop() ?? trimmed;
      if (/^[A-Za-z0-9_$]+$/.test(name)) {
        names.add(name);
      }
    }
  }

  return Array.from(names);
}

function moduleObservations(lines: number, exportedNames: string[]): string[] {
  const exportSummary =
    exportedNames.length > 0 ? `exports: ${exportedNames.join(", ")}` : "exports: none";
  return [`${lines} lines`, exportSummary];
}

function recordModule(indexed: IndexedModule[], path: string, lines: number) {
  indexed.push({ path, lines });
}

function recordFailure(failures: string[], key: string, error: unknown) {
  failures.push(`${key}: ${String(error)}`);
}

function addRelation(relations: GraphRelation[], from: string, to: string) {
  relations.push({ from, to, relationType: "belongs to" });
}

function reachedExpected(actual: number, expected: number): boolean {
  return actual >= expected;
}

function buildReport(indexed: IndexedModule[], failures: string[]): string {
  const lines: string[] = ["# Index report", "", `Modules indexed: ${indexed.length}`, ""];
  for (const mod of indexed) {
    lines.push(`- ${mod.path} (${mod.lines} lines)`);
  }
  lines.push("", `Failures: ${failures.length}`);
  for (const failure of failures) {
    lines.push(`- ${failure}`);
  }
  return lines.join("\n");
}

export default async function flow(
  input: { root: string; maxModules: number },
  tools: Tools
) {
  const repositoryCreated = await tools.memory.createEntities({
    entities: [{ name: input.root, entityType: "repository", observations: [] }],
  });

  const searchResults = await tools.fs.searchFiles({ path: input.root, pattern: "*.ts" });
  const candidates = parsePaths(searchResults.content);
  const selected = limitTo(candidates, input.maxModules);

  const indexedModules: IndexedModule[] = [];
  const failures: string[] = [];
  const relations: GraphRelation[] = [];

  for (const path of selected) {
    let lines = 0;
    let exportedNames: string[] = [];
    try {
      const file = await tools.fs.readTextFile({ path });
      const counted = countLines(file.content);
      const found = extractExports(file.content);
      lines = counted;
      exportedNames = found;
    } catch (error) {
      recordFailure(failures, path, error);
      continue;
    }

    const observations = moduleObservations(lines, exportedNames);
    const moduleEntity = await tools.memory.createEntities({
      entities: [{ name: path, entityType: "module", observations }],
    });
    recordModule(indexedModules, path, lines);
    addRelation(relations, path, input.root);
  }

  if (relations.length > 0) {
    const relationsLinked = await tools.memory.createRelations({ relations });
  }

  const expectedEntities = 1 + indexedModules.length;
  let attempts = 0;
  let settled = false;
  while (!settled && attempts < 3) {
    attempts += 1;
    const graph = await tools.memory.readGraph({});
    const enough = reachedExpected(graph.entities.length, expectedEntities);
    settled = enough;
  }

  const report = buildReport(indexedModules, failures);
  const reportWritten = await tools.fs.writeFile({
    path: `${input.root}/index-report.md`,
    content: report,
  });

  return {
    modulesIndexed: indexedModules.length,
    modulesFailed: failures.length,
    settleAttempts: attempts,
  };
}

