import type { Tools } from "../generated/tools";

interface ReadEntry {
  path: string;
  size: number;
}

interface MissingEntry {
  path: string;
  reason: string;
}

function joinPath(root: string, relativePath: string) {
  return `${root}/${relativePath}`;
}

function isEmptyContent(content: string) {
  return content.length === 0;
}

function serverMessage(error: unknown) {
  return String(error);
}

function recordRead(entries: ReadEntry[], path: string, size: number) {
  entries.push({ path, size });
}

function recordMissing(entries: MissingEntry[], path: string, error: unknown) {
  entries.push({ path, reason: serverMessage(error) });
}

function renderReport(readEntries: ReadEntry[], missingEntries: MissingEntry[]) {
  const lines: string[] = [];
  lines.push("## read");
  for (const entry of readEntries) {
    lines.push(`- ${entry.path} (${entry.size} chars)`);
  }
  lines.push("");
  lines.push("## missing");
  for (const entry of missingEntries) {
    lines.push(`- ${entry.path}: ${entry.reason}`);
  }
  return lines.join("\n");
}

export default async function flow(
  input: { root: string; maxFiles: number },
  tools: Tools
) {
  const checklist: string[] = [
    "orders.ts",
    "docs/session.md",
    "money.ts",
    "MISSING-ONE.md",
    "session.ts",
    "docs/orders.md",
    "nope/deep/other.md",
    "index.ts",
  ];

  if (checklist.length === 0) {
    return { read: 0 };
  }

  const readEntries: ReadEntry[] = [];
  const missingEntries: MissingEntry[] = [];
  let readCount = 0;
  let limitCutRunShort = false;

  for (const relativePath of checklist) {
    if (readCount === input.maxFiles) {
      limitCutRunShort = true;
      break;
    }

    const fullPath = joinPath(input.root, relativePath);

    let content: string;
    try {
      const file = await tools.fs.readTextFile({ path: fullPath });
      content = file.content;
    } catch (error) {
      recordMissing(missingEntries, fullPath, error);
      continue;
    }

    if (isEmptyContent(content)) {
      continue;
    }

    recordRead(readEntries, fullPath, content.length);
    readCount += 1;
  }

  const reportPath = joinPath(input.root, "read-report.md");
  const report = renderReport(readEntries, missingEntries);
  await tools.fs.writeFile({ path: reportPath, content: report });

  return {
    read: readCount,
    missing: missingEntries.length,
    limitCutRunShort,
  };
}

import type { Tools } from "../generated/tools";

type ModuleGrade = "large" | "documented" | "plain";

interface GradedModule {
  name: string;
  grade: ModuleGrade;
}

/** Turns the raw searchFiles listing into module paths, capped at maxModules. */
function parseModulePaths(listing: string, maxModules: number): string[] {
  return listing
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length > 0)
    .slice(0, Math.max(0, maxModules));
}

function moduleName(modulePath: string): string {
  const parts = modulePath.split(/[\\/]/);
  return parts[parts.length - 1];
}

/** Size in bytes: prefer the reported metadata, fall back to the text length. */
function fileSizeInBytes(infoContent: string, textContent: string): number {
  const jsonSize = infoContent.match(/"size"\s*:\s*(\d+)/);
  if (jsonSize) {
    return Number(jsonSize[1]);
  }
  const humanSize = infoContent.match(/(\d+)\s*bytes/i);
  if (humanSize) {
    return Number(humanSize[1]);
  }
  return textContent.length;
}

/**
 * Grading rubric:
 * - "large" when the file is over 200 bytes,
 * - "documented" when its text contains a JSDoc block ("/**"),
 * - "plain" otherwise.
 */
function gradeModule(sizeBytes: number, text: string): ModuleGrade {
  if (sizeBytes > 200) {
    return "large";
  }
  if (text.includes("/**")) {
    return "documented";
  }
  return "plain";
}

function recordFailure(failures: string[], modulePath: string, error: unknown) {
  failures.push(`${moduleName(modulePath)} could not be audited: ${String(error)}`);
}

function recordModule(graded: GradedModule[], modulePath: string, grade: ModuleGrade) {
  graded.push({ name: moduleName(modulePath), grade });
}

function countByGrade(graded: GradedModule[]): Record<ModuleGrade, number> {
  const counts: Record<ModuleGrade, number> = { large: 0, documented: 0, plain: 0 };
  for (const item of graded) {
    counts[item.grade] += 1;
  }
  return counts;
}

function buildAuditReport(
  graded: GradedModule[],
  failures: string[],
  thoughtsRecorded: number
): string {
  const lines: string[] = ["# Repository audit", "", "## modules", ""];
  for (const item of graded) {
    lines.push(`- ${item.name}: ${item.grade}`);
  }
  if (failures.length > 0) {
    lines.push("", "## unreadable modules", "");
    for (const failure of failures) {
      lines.push(`- ${failure}`);
    }
  }
  lines.push(
    "",
    "## reasoning",
    "",
    `The audit was reasoned through in exactly ${thoughtsRecorded} sequential thoughts (1 of 3, 2 of 3, 3 of 3); no further thought was needed.`
  );
  return lines.join("\n");
}

export default async function flow(
  input: { root: string; maxModules: number },
  tools: Tools
) {
  // Gather three independent views of the root at the same time.
  const [sizes, tree, allowedDirs] = await Promise.all([
    tools.fs.listDirectoryWithSizes({ path: input.root }),
    tools.fs.directoryTree({ path: input.root }),
    tools.fs.listAllowedDirectories({}),
  ]);

  const found = await tools.fs.searchFiles({ path: input.root, pattern: "*.ts" });
  const candidates = parseModulePaths(found.content, input.maxModules);

  const graded: GradedModule[] = [];
  const failures: string[] = [];

  for (const modulePath of candidates) {
    try {
      const info = await tools.fs.getFileInfo({ path: modulePath });
      const source = await tools.fs.readTextFile({ path: modulePath });
      const size = fileSizeInBytes(info.content, source.content);
      const grade = gradeModule(size, source.content);
      recordModule(graded, modulePath, grade);
    } catch (error) {
      recordFailure(failures, modulePath, error);
    }
  }

  const counts = countByGrade(graded);

  // Think the audit through in exactly three numbered thoughts.
  const thought1 = await tools.reasoning.sequentialThinking({
    thought: `Inventory: root listing (${sizes.content.split("\n").length} entries), recursive tree, and allowed directories were gathered in parallel. Selected ${candidates.length} TypeScript modules (limit ${input.maxModules}); ${graded.length} graded, ${failures.length} skipped as unreadable.`,
    thoughtNumber: 1,
    totalThoughts: 3,
  });
  const thought2 = await tools.reasoning.sequentialThinking({
    thought: `Grading applied per module: over 200 bytes means large, otherwise a "/**" JSDoc block means documented, otherwise plain. Distribution so far: ${counts.large} large, ${counts.documented} documented, ${counts.plain} plain.`,
    thoughtNumber: 2,
    totalThoughts: 3,
  });
  const thought3 = await tools.reasoning.sequentialThinking({
    thought: `Conclusion: write audit.md at the repository root listing every module's grade and a reasoning section noting that ${thought1.totalThoughts} thoughts were taken. Audit complete.`,
    thoughtNumber: 3,
    totalThoughts: 3,
    nextThoughtNeeded: false,
  });

  const thoughtsRecorded = thought3.thoughtNumber;

  const report = buildAuditReport(graded, failures, thoughtsRecorded);
  const saved = await tools.fs.writeFile({
    path: `${input.root}/audit.md`,
    content: report,
  });

  return {
    large: counts.large,
    documented: counts.documented,
    plain: counts.plain,
    thoughtsRecorded,
    modulesAudited: graded.length,
    unreadable: failures.length,
  };
}

