interface ReadEntry {
  path: string;
  chars: number;
}

interface MissingEntry {
  path: string;
  reason: string;
}

const CHECKLIST: string[] = [
  "orders.ts",
  "docs/session.md",
  "money.ts",
  "MISSING-ONE.md",
  "session.ts",
  "docs/orders.md",
  "nope/deep/other.md",
  "index.ts",
];

function absPath(root: string, relative: string): string {
  return `${root}/${relative}`;
}

function recordRead(reads: ReadEntry[], path: string, content: string) {
  reads.push({ path, chars: content.length });
}

function recordMissing(missing: MissingEntry[], path: string, error: unknown) {
  missing.push({
    path,
    reason: error instanceof Error ? error.message : String(error),
  });
}

function buildReport(reads: ReadEntry[], missing: MissingEntry[]): string {
  const lines: string[] = [];

  lines.push("## read");
  for (const entry of reads) {
    lines.push(`- ${entry.path} (${entry.chars} chars)`);
  }

  lines.push("");
  lines.push("## missing");
  for (const entry of missing) {
    lines.push(`- ${entry.path}: ${entry.reason}`);
  }

  return lines.join("\n");
}

export default async function flow(
  input: { root: string; maxFiles: number },
  tools: Tools
) {
  if (CHECKLIST.length === 0) {
    return { read: 0 };
  }

  const reads: ReadEntry[] = [];
  const missing: MissingEntry[] = [];
  let readCount = 0;
  let stoppedByLimit = false;

  for (const relative of CHECKLIST) {
    if (readCount >= input.maxFiles) {
      stoppedByLimit = true;
      break;
    }

    const path = absPath(input.root, relative);

    let content = "";
    try {
      const file = await tools.fs.readTextFile({ path });
      content = file.content;
    } catch (error) {
      recordMissing(missing, relative, error);
      continue;
    }

    if (content.length === 0) {
      continue;
    }

    recordRead(reads, relative, content);
    readCount += 1;
  }

  const reportContent = buildReport(reads, missing);
  const reportPath = absPath(input.root, "read-report.md");
  await tools.fs.writeFile({ path: reportPath, content: reportContent });

  return {
    read: readCount,
    missing: missing.length,
    limitReached: stoppedByLimit,
  };
}

