type Failure = { path: string; reason: string };
type BatchEntry = { path: string; text: string; readError: string | null };

function describeError(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

function recordFailure(failures: Failure[], path: string, reason: string) {
  failures.push({ path, reason });
}

function baseName(path: string): string {
  const parts = path.split("/");
  return parts[parts.length - 1];
}

function withMigrationMarker(text: string): string {
  if (text.trim().length === 0) {
    return "";
  }
  return `<!-- migrated -->\n${text}`;
}

function selectNotePaths(raw: string, archiveDir: string): string[] {
  const paths: string[] = [];
  for (const line of raw.split("\n")) {
    const candidate = line.trim();
    if (!candidate.endsWith(".md")) {
      continue;
    }
    // never migrate the archive into itself
    if (candidate.startsWith(`${archiveDir}/`)) {
      continue;
    }
    paths.push(candidate);
  }
  return paths;
}

function chunkPaths(paths: string[], size: number): string[][] {
  const safeSize = Math.max(1, Math.floor(size));
  const batches: string[][] = [];
  for (let i = 0; i < paths.length; i += safeSize) {
    batches.push(paths.slice(i, i + safeSize));
  }
  return batches;
}

function failedBatchEntries(paths: string[], reason: string): BatchEntry[] {
  const entries: BatchEntry[] = [];
  for (const path of paths) {
    entries.push({ path, text: "", readError: reason });
  }
  return entries;
}

function parseBatchResponse(raw: string, expectedPaths: string[]): BatchEntry[] {
  const entries: BatchEntry[] = [];
  for (const path of expectedPaths) {
    const marker = `${path}:`;
    const start = raw.indexOf(marker);
    if (start === -1) {
      entries.push({ path, text: "", readError: "missing from batch read result" });
      continue;
    }
    let end = raw.length;
    for (const other of expectedPaths) {
      if (other === path) {
        continue;
      }
      const candidate = raw.indexOf(`${other}:`, start + marker.length);
      if (candidate !== -1 && candidate < end) {
        end = candidate;
      }
    }
    const section = raw
      .slice(start + marker.length, end)
      .replace(/^\r?\n/, "")
      .replace(/\r?\n\s*$/, "");
    if (section.startsWith("Error")) {
      entries.push({ path, text: "", readError: section });
    } else {
      entries.push({ path, text: section, readError: null });
    }
  }
  return entries;
}

function renderReport(
  migrated: number,
  skipped: number,
  failures: Failure[],
  abandoned: boolean
): string {
  const lines: string[] = [];
  lines.push("# Migration report");
  lines.push("");
  lines.push(`Migrated: ${migrated}`);
  lines.push(`Skipped (empty): ${skipped}`);
  lines.push(`Failed: ${failures.length}`);
  lines.push(`Abandoned: ${abandoned ? "yes" : "no"}`);
  if (failures.length > 0) {
    lines.push("");
    lines.push("## Failures");
    for (const failure of failures) {
      lines.push(`- ${failure.path}: ${failure.reason}`);
    }
  }
  return `${lines.join("\n")}\n`;
}

export default async function flow(
  input: { root: string; batchSize: number; maxFailures: number },
  tools: Tools
) {
  const archiveDir = `${input.root}/archive`;
  const reportPath = `${input.root}/migration-report.md`;

  // 1. destination directory exists before anything is written
  await tools.fs.createDirectory({ path: archiveDir });

  // 2. find every *.md file under the root
  const searchResult = await tools.fs.searchFiles({
    path: input.root,
    pattern: "**/*.md",
  });
  const notePaths = selectNotePaths(searchResult.content, archiveDir);

  if (notePaths.length === 0) {
    await tools.fs.writeFile({ path: reportPath, content: "" });
    return { migrated: 0, skipped: 0, failed: 0, abandoned: false };
  }

  const batches = chunkPaths(notePaths, input.batchSize);

  let migrated = 0;
  let skipped = 0;
  let abandoned = false;
  const failures: Failure[] = [];

  // 3. loop over batches, loop over notes inside each batch
  for (const batch of batches) {
    if (abandoned) {
      break;
    }

    let entries: BatchEntry[] = [];
    try {
      const batchRead = await tools.fs.readMultipleFiles({ paths: batch });
      const parsedEntries = parseBatchResponse(batchRead.content, batch);
      entries = parsedEntries;
    } catch (error) {
      const reason = describeError(error);
      const failedEntries = failedBatchEntries(batch, reason);
      entries = failedEntries;
    }

    for (const entry of entries) {
      // 6. a note that failed to read is a failure
      if (entry.readError !== null) {
        recordFailure(failures, entry.path, entry.readError);
        if (failures.length > input.maxFailures) {
          abandoned = true;
          break;
        }
        continue;
      }

      // 4. transform, skipping notes that are empty afterwards
      const transformed = withMigrationMarker(entry.text);
      if (transformed.length === 0) {
        skipped += 1;
        continue;
      }

      // 5. destination keeps the original file name
      const fileName = baseName(entry.path);
      const destination = `${archiveDir}/${fileName}`;

      try {
        await tools.fs.writeFile({ path: destination, content: transformed });
        // 7. record the migrated note in the knowledge graph
        await tools.memory.createEntities({
          entities: [
            { name: entry.path, entityType: "note", observations: [destination] },
          ],
        });
      } catch (error) {
        // 6. a note that fails to write is a failure; carry on unless over budget
        recordFailure(failures, entry.path, describeError(error));
        if (failures.length > input.maxFailures) {
          abandoned = true;
          break;
        }
        continue;
      }

      migrated += 1;
    }
  }

  // 8. final report with counts and failures
  const report = renderReport(migrated, skipped, failures, abandoned);
  await tools.fs.writeFile({ path: reportPath, content: report });

  return {
    migrated,
    skipped,
    failed: failures.length,
    abandoned,
  };
}

