import type { Tools } from "../generated/tools";

type StatusLocation = "New York" | "Chicago" | "Los Angeles";

const STATUS_LOCATIONS: StatusLocation[] = ["New York", "Chicago", "Los Angeles"];

function pickLocation(cycle: number): StatusLocation {
  return STATUS_LOCATIONS[(cycle - 1) % STATUS_LOCATIONS.length];
}

function recordReading(
  readings: string[],
  cycle: number,
  location: StatusLocation,
  temperature: number,
  conditions: string
) {
  readings.push(`Cycle ${cycle} — ${location}: ${temperature}°C, ${conditions}`);
}

function recordFailure(failures: string[], cycle: number, location: StatusLocation, error: unknown) {
  failures.push(`Cycle ${cycle} (${location}) failed: ${String(error)}`);
}

// getSum is typed as returning void in the generated tools file, so the
// numeric total has to be recovered from whatever the server resolves with.
function asNumber(value: unknown): number {
  if (typeof value === "number") {
    return value;
  }
  if (typeof value === "string") {
    const parsed = Number.parseFloat(value);
    return Number.isNaN(parsed) ? 0 : parsed;
  }
  return 0;
}

function averageTemperature(total: number, count: number): number {
  if (count === 0) {
    return 0;
  }
  return Math.round((total / count) * 100) / 100;
}

function buildDigest(
  readings: string[],
  failures: string[],
  totalCycles: number,
  successfulCycles: number,
  failedCycles: number,
  avgTemp: number
): string {
  const sections: string[] = [];
  sections.push("# Status digest", "");
  sections.push("## Readings");
  for (const line of readings) {
    sections.push(`- ${line}`);
  }
  if (failures.length > 0) {
    sections.push("", "## Failed cycles");
    for (const line of failures) {
      sections.push(`- ${line}`);
    }
  }
  sections.push("", "## Totals");
  sections.push(`- Total cycles: ${totalCycles}`);
  sections.push(`- Successful cycles: ${successfulCycles}`);
  sections.push(`- Failed cycles: ${failedCycles}`);
  sections.push(`- Average temperature: ${avgTemp.toFixed(1)}°C`);
  return sections.join("\n");
}

export default async function flow(
  input: { root: string; maxCycles: number },
  tools: Tools
) {
  if (input.maxCycles < 1) {
    return { cycles: 0 };
  }

  let cyclesPolled = 0;
  let successfulCycles = 0;
  let failedCycles = 0;
  let totalTemperature = 0;
  const readings: string[] = [];
  const failures: string[] = [];

  while (cyclesPolled < input.maxCycles) {
    cyclesPolled += 1;
    const location = pickLocation(cyclesPolled);

    await tools.everything.echo({
      message: `Status poll cycle ${cyclesPolled} of ${input.maxCycles}: checking ${location}`
    });

    try {
      const status = await tools.everything.getStructuredContent({ location });
      totalTemperature += status.temperature;
      recordReading(readings, cyclesPolled, location, status.temperature, status.conditions);
      successfulCycles += 1;
    } catch (error) {
      recordFailure(failures, cyclesPolled, location, error);
      failedCycles += 1;
      continue;
    }
  }

  const sumResult = await tools.everything.getSum({
    a: successfulCycles,
    b: failedCycles
  });
  const totalCycles = asNumber(sumResult);

  const avgTemp = averageTemperature(totalTemperature, successfulCycles);
  const digest = buildDigest(readings, failures, totalCycles, successfulCycles, failedCycles, avgTemp);

  await tools.fs.writeFile({
    path: `${input.root}/digest.md`,
    content: digest
  });

  return { cycles: cyclesPolled, failed: failedCycles, averageTemperature: avgTemp };
}

import type { Tools } from "../generated/tools";

interface NoteRead {
  path: string;
  text: string | null;
  error?: string;
}

interface RecordedFailure {
  path: string;
  reason: string;
}

function parseFoundPaths(listing: string): string[] {
  return listing
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length > 0);
}

function chunkPaths(paths: string[], size: number): string[][] {
  const width = Math.max(1, Math.floor(size));
  const chunks: string[][] = [];
  for (let index = 0; index < paths.length; index += width) {
    chunks.push(paths.slice(index, index + width));
  }
  return chunks;
}

// The batch reader returns the requested files' contents separated by a
// "---" line, in the same order as the requested paths.
function splitBatchContent(content: string, paths: string[]): NoteRead[] {
  const sections = content.split("\n---\n");
  return paths.map((path, index) => {
    const text = sections[index];
    if (text === undefined) {
      return { path, text: null, error: "missing from batch read" };
    }
    return { path, text, error: undefined };
  });
}

function transformNote(raw: string): string {
  return `<!-- migrated -->\n${raw}`;
}

function isEmptyNote(transformed: string): boolean {
  return transformed.replace("<!-- migrated -->", "").trim() === "";
}

function archivePathFor(root: string, originalPath: string): string {
  const fileName = originalPath.split("/").pop() ?? originalPath;
  return `${root}/archive/${fileName}`;
}

function recordFailure(failures: RecordedFailure[], path: string, error: unknown) {
  failures.push({ path, reason: String(error) });
}

function tooManyFailures(failureCount: number, maxFailures: number): boolean {
  return failureCount > maxFailures;
}

function buildReport(
  migrated: number,
  skipped: number,
  failures: RecordedFailure[],
  abandoned: boolean
): string {
  const lines = [
    "# Migration report",
    "",
    `- Migrated: ${migrated}`,
    `- Skipped: ${skipped}`,
    `- Failed: ${failures.length}`,
    `- Abandoned: ${abandoned ? "yes" : "no"}`,
    "",
    "## Failures",
    "",
  ];
  if (failures.length === 0) {
    lines.push("None.");
  }
  for (const failure of failures) {
    lines.push(`- ${failure.path}: ${failure.reason}`);
  }
  return lines.join("\n");
}

export default async function flow(
  input: { root: string; batchSize: number; maxFailures: number },
  tools: Tools
) {
  await tools.fs.createDirectory({ path: `${input.root}/archive` });

  const found = await tools.fs.searchFiles({ path: input.root, pattern: "**/*.md" });
  const notePaths = parseFoundPaths(found.content);

  if (notePaths.length === 0) {
    const emptyReport = buildReport(0, 0, [], false);
    await tools.fs.writeFile({
      path: `${input.root}/migration-report.md`,
      content: emptyReport,
    });
    return { migrated: 0, skipped: 0, failed: 0, abandoned: false };
  }

  const batches = chunkPaths(notePaths, input.batchSize);

  let migrated = 0;
  let skipped = 0;
  let abandoned = false;
  const failures: RecordedFailure[] = [];

  for (const batch of batches) {
    let batchNotes: NoteRead[] = [];
    try {
      const combined = await tools.fs.readMultipleFiles({ paths: batch });
      const parsed = splitBatchContent(combined.content, batch);
      batchNotes = parsed;
    } catch (error) {
      for (const path of batch) {
        recordFailure(failures, path, error);
      }
    }

    if (tooManyFailures(failures.length, input.maxFailures)) {
      abandoned = true;
      break;
    }

    for (const note of batchNotes) {
      if (note.text === null) {
        recordFailure(failures, note.path, note.error ?? "could not be read");
        if (tooManyFailures(failures.length, input.maxFailures)) {
          abandoned = true;
          break;
        }
        continue;
      }

      const transformed = transformNote(note.text);

      if (isEmptyNote(transformed)) {
        skipped += 1;
        continue;
      }

      const destination = archivePathFor(input.root, note.path);

      try {
        const archived = await tools.fs.writeFile({
          path: destination,
          content: transformed,
        });
      } catch (error) {
        recordFailure(failures, note.path, error);
        if (tooManyFailures(failures.length, input.maxFailures)) {
          abandoned = true;
          break;
        }
        continue;
      }

      const recorded = await tools.memory.createEntities({
        entities: [
          { name: note.path, entityType: "note", observations: [destination] },
        ],
      });
      migrated += 1;
    }

    if (abandoned) {
      break;
    }
  }

  const report = buildReport(migrated, skipped, failures, abandoned);
  await tools.fs.writeFile({
    path: `${input.root}/migration-report.md`,
    content: report,
  });

  return {
    migrated,
    skipped,
    failed: failures.length,
    abandoned,
  };
}

