interface NoteRead {
  path: string;
  text: string | null;
  error?: string;
}

interface RecordedFailure {
  path: string;
  reason: string;
}

interface MigratedNote {
  from: string;
  to: string;
}

function parseFoundPaths(listing: string): string[] {
  return listing
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length > 0);
}

function chunkPaths(paths: string[], size: number): string[][] {
  const width = Math.max(1, Math.floor(size));
  const chunks: string[][] = [];
  for (let index = 0; index < paths.length; index += width) {
    chunks.push(paths.slice(index, index + width));
  }
  return chunks;
}

// readMultipleFiles answers with one section per requested file, joined by
// "---" lines. Each section is "<path>:\n<contents>\n", or "<path>: Error - ..."
// when that file could not be read.
function parseNoteSection(section: string): NoteRead | null {
  const headerEnd = section.indexOf(":\n");
  if (headerEnd === -1) {
    const errorMarker = section.indexOf(": Error - ");
    if (errorMarker === -1) {
      return null;
    }
    return {
      path: section.slice(0, errorMarker),
      text: null,
      error: section.slice(errorMarker + ": Error - ".length),
    };
  }
  const path = section.slice(0, headerEnd);
  let text = section.slice(headerEnd + 2);
  if (text.endsWith("\n")) {
    text = text.slice(0, -1);
  }
  return { path, text, error: undefined };
}

function collectBatchNotes(batch: string[], content: string): NoteRead[] {
  const sections = content.split("\n---\n").map(parseNoteSection);
  return batch.map((path) => {
    const match = sections.find((section) => section !== null && section.path === path);
    if (!match) {
      return { path, text: null, error: "missing from batch read" };
    }
    return match;
  });
}

function transformNote(raw: string): string {
  return `<!-- migrated -->\n${raw}`;
}

function isEmptyTransformedNote(transformed: string): boolean {
  return transformed.replace("<!-- migrated -->", "").trim() === "";
