  migratedNotes.push({ from, to });
}

function recordSkipped(skippedNotes: string[], path: string) {
  skippedNotes.push(path);
}

function tooManyFailures(failureCount: number, maxFailures: number): boolean {
  return failureCount > maxFailures;
}

function buildReport(
  migratedNotes: MigratedNote[],
  skippedNotes: string[],
  failures: RecordedFailure[],
  abandoned: boolean
): string {
  const lines = [
    "# Migration report",
