    const emptyReport = buildReport([], [], [], false);
    await tools.fs.writeFile({
      path: `${input.root}/migration-report.md`,
      content: emptyReport,
    });
    return { migrated: 0, skipped: 0, failed: 0, abandoned: false };
  }

  const batches = chunkPaths(notePaths, input.batchSize);

  const migratedNotes: MigratedNote[] = [];
  const skippedNotes: string[] = [];
  const failures: RecordedFailure[] = [];
  let abandoned = false;

  for (const batch of batches) {
    let batchNotes: NoteRead[] = [];
    try {
      const combined = await tools.fs.readMultipleFiles({ paths: batch });
      const parsed = collectBatchNotes(batch, combined.content);
      batchNotes = parsed;
    } catch (error) {
      for (const path of batch) {
        recordFailure(failures, path, error);
      }
    }

    if (tooManyFailures(failures.length, input.maxFailures)) {
      abandoned = true;
      break;
    }

    for (const note of batchNotes) {
      if (note.text === null) {
        recordFailure(failures, note.path, note.error ?? "could not be read");
        if (tooManyFailures(failures.length, input.maxFailures)) {
          abandoned = true;
          break;
        }
        continue;
      }

      const transformed = transformNote(note.text);

      if (isEmptyTransformedNote(transformed)) {
        recordSkipped(skippedNotes, note.path);
        continue;
      }

      const destination = archivePathFor(input.root, note.path);

      try {
        const archived = await tools.fs.writeFile({
          path: destination,
          content: transformed,
        });
      } catch (error) {
        recordFailure(failures, note.path, error);
        if (tooManyFailures(failures.length, input.maxFailures)) {
          abandoned = true;
          break;
        }
        continue;
      }

      const recorded = await tools.memory.createEntities({
        entities: [
          { name: note.path, entityType: "note", observations: [destination] },
        ],
      });
      recordMigrated(migratedNotes, note.path, destination);
    }

    if (abandoned) {
      break;
    }
  }

  const report = buildReport(migratedNotes, skippedNotes, failures, abandoned);
  await tools.fs.writeFile({
    path: `${input.root}/migration-report.md`,
    content: report,
  });

  return {
    migrated: migratedNotes.length,
    skipped: skippedNotes.length,
    failed: failures.length,
    abandoned,
  };
}

import type { Tools } from "../generated/tools";

const LOCATIONS = ["New York", "Chicago", "Los Angeles"] as const;

type StatusLocation = (typeof LOCATIONS)[number];

function locationForCycle(cycle: number): StatusLocation {
  return LOCATIONS[(cycle - 1) % LOCATIONS.length];
}

function recordFailure(failures: string[], cycle: number, error: unknown) {
  failures.push(`cycle ${cycle}: ${String(error)}`);
}

function recordLine(lines: string[], line: string) {
  lines.push(line);
}

function successLine(cycle: number, location: string, temperature: number, conditions: string): string {
  return `- cycle ${cycle}: ${location} - ${temperature} degrees, ${conditions}`;
}

function failureLine(cycle: number, location: string, error: unknown): string {
  return `- cycle ${cycle}: ${location} - FAILED (${String(error)})`;
}

// getSum is declared to resolve void; coerce whatever the service actually
// returns, falling back to the locally counted total if nothing usable comes back.
function asCount(value: unknown, fallback: number): number {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function averageTemperature(total: number, count: number): number {
  if (count === 0) {
    return 0;
  }
  return total / count;
}

function totalsBlock(totalCycles: number, succeeded: number, failed: number, average: number): string {
  return [
    "",
    "## Totals",
    `- cycles: ${totalCycles}`,
    `- successful: ${succeeded}`,
    `- failed: ${failed}`,
    `- average temperature: ${average.toFixed(1)} degrees`
  ].join("\n");
}

function buildDigest(lines: string[], totals: string): string {
  return ["# Status digest", "", ...lines, totals].join("\n") + "\n";
}

function digestPathFor(root: string): string {
  return `${root}/digest.md`;
}

export default async function flow(
  input: { root: string; maxCycles: number },
  tools: Tools
) {
  if (input.maxCycles < 1) {
    return { cycles: 0 };
  }

  const failures: string[] = [];
  const lines: string[] = [];
  let cycle = 0;
  let succeeded = 0;
  let failed = 0;
  let temperatureTotal = 0;

  while (cycle < input.maxCycles) {
    cycle += 1;

    await tools.everything.echo({ message: `Status poll cycle ${cycle} of ${input.maxCycles}` });

    const location = locationForCycle(cycle);

    let status: { temperature: number; conditions: string } | null = null;
    try {
      const fetched = await tools.everything.getStructuredContent({ location });
      status = fetched;
    } catch (error) {
      failed += 1;
      recordFailure(failures, cycle, error);
      const line = failureLine(cycle, location, error);
      recordLine(lines, line);
    }

    if (status === null) {
      continue;
    }

    succeeded += 1;
    temperatureTotal += status.temperature;
    const line = successLine(cycle, location, status.temperature, status.conditions);
    recordLine(lines, line);
  }

  const sumReply = await tools.everything.getSum({ a: succeeded, b: failed });
  const totalCycles = asCount(sumReply, succeeded + failed);

  const average = averageTemperature(temperatureTotal, succeeded);

  const totals = totalsBlock(totalCycles, succeeded, failed, average);
  const digestBody = buildDigest(lines, totals);

  const digestPath = digestPathFor(input.root);
  await tools.fs.writeFile({ path: digestPath, content: digestBody });

  return { cycles: cycle, failed, averageTemperature: average };
}
